CREATE TABLE IF NOT EXISTS despachos (
    id INT PRIMARY KEY AUTO_INCREMENT,
    nombre VARCHAR(150) NOT NULL,
    direccion VARCHAR(255) NOT NULL,
    codigo_postal VARCHAR(10) NOT NULL,
    ciudad VARCHAR(100) NOT NULL,
    pais VARCHAR(50) DEFAULT 'España',
    telefono VARCHAR(50),
    whatsapp VARCHAR(50)
);

VALUES ('TrueGrid Leaf Abogados', 'Gran Vía, 69, 7ª pl. of. 712', '28013', 'Madrid', 'España', '+91 9582113764', '+91 9582113764');

CREATE TABLE IF NOT EXISTS letrados (
    id INT PRIMARY KEY AUTO_INCREMENT,
    nombre VARCHAR(120) NOT NULL,
    colegiado VARCHAR(50) NOT NULL,
    cargo VARCHAR(150) NOT NULL,
    universidad VARCHAR(150),
    especialidad VARCHAR(200),
    idiomas VARCHAR(150),
    foto VARCHAR(100)
);


CREATE TABLE IF NOT EXISTS servicios_juridicos (
    id INT PRIMARY KEY,
    categoria_slug VARCHAR(50) NOT NULL,
    categoria_nombre VARCHAR(100) NOT NULL,
    titulo VARCHAR(255) NOT NULL,
    descripcion TEXT NOT NULL,
    plazo_estimado VARCHAR(100) NOT NULL,
    honorarios VARCHAR(100) NOT NULL
);

